% BIAS_SCURVE  Interpolation-bias S-curve self-test (Schreier et al. 2000).
%
% Sweeps a rigid HORIZONTAL subpixel shift delta = 0..1 px applied to a
% synthetic periodic speckle and measures the engine's systematic
% displacement error vs subpixel position - the classic bias "S-curve"
% caused by intensity interpolation (Schreier, Braasch & Sutton 2000,
% Opt. Eng. 39(11):2915, doi:10.1117/1.1314593).
%
% Method details that matter:
%   * the shifted images are generated by a PURE FOURIER PHASE SHIFT of a
%     PERIODIC speckle - no spatial interpolation anywhere in the
%     generator, so the test measures the ENGINE's bias, not the
%     generator's (Schreier 2000, Sec. 4.1 requirement);
%   * the speckle is white noise Gaussian-filtered IN THE FOURIER DOMAIN
%     (circular), so the pattern and its shift are exactly periodic and
%     edge-free; sigma = 2.0 px matches the rigid-shift self-test speckle
%     in dic_icgn.m, sigma = 1.0 px is a harsher pattern (more
%     high-wavenumber energy -> larger bias, per Schreier);
%   * the bias at each delta is the mean over ~3000 subsets, so pattern-
%     induced scatter averages out; conv_tol is tightened to 1e-4 px so
%     solver truncation sits well below the ~1e-3 px bias being measured.
%
% Reported per pattern/subset combination:
%   * b            = max |mean u error| over the sweep (S-curve amplitude);
%   * app. strain  = max |d(bias)/d(delta)| (slope of the S-curve = the
%                    relative apparent strain the interpolant can fake,
%                    Delta eps / eps - Schreier's headline metric);
%   * cross-talk   = max |mean v error| (must be ~0; no shift applied in y).
%
% Context: cubic-polynomial interpolation is worst-case ~4-5 % apparent
% strain on harsh patterns, quintic B-spline < 2 % (Schreier 2000, Table).
% LiteDIC uses MATLAB griddedInterpolant 'spline' (cubic spline). This
% test also gives the engine-level driver behind the Star 6 long-period
% amplitude excess of +3-4 % seen in the Challenge 2.0 benchmark: there
% the +-2.4 px sinusoidal swing traverses the S-curve ~5 times per period,
% pushing bias energy to the signal frequency. Exact propagation from the
% S-curve to that number depends on the full curve shape (Bessel-function
% mixing), so compare orders of magnitude, not digits.
%
% Outputs: console summary, S-curve figure, bias_scurve_results.mat.
% Runtime: a few minutes (dic_engine_batch, all CPU cores).
% No toolboxes required - plain MATLAB on any CPU.

close all; clc; clear;

%% ===================== Configuration =====================
deltas  = 0:0.05:1;          % swept horizontal shifts, px
sigmas  = [2.0 1.0];         % speckle correlation radii, px (see header)
subsets = [21 41];           % subset sizes, px (odd)
N       = 256;               % periodic speckle size, px

P.grid_step    = 4;          % dense grid -> ~3000 averaged points
P.search_range = 2;          % shifts are subpixel; seed search is cheap
P.black_thr    = 0.2;
P.zncc_min     = 0.5;
P.max_iter     = 30;
P.conv_tol     = 1e-4;       % below the bias scale being measured

this_dir = fileparts(mfilename('fullpath'));
if isempty(this_dir), this_dir = pwd; end
addpath(this_dir);           % dic_engine_batch.m

%% ===================== Sweep =====================
res = struct('sigma', {}, 'subset', {}, 'delta', {}, ...
             'bias_u', {}, 'bias_v', {}, 'scatter_u', {}, 'npts', {});
t_all = tic;
for sg = sigmas
    % periodic speckle: white noise x Gaussian transfer in Fourier domain
    rng(0);
    W  = fft2(rand(N));
    k  = ifftshift(-floor(N/2):ceil(N/2)-1) * (2*pi/N);
    [KX, KY] = meshgrid(k, k);
    H  = exp(-(KX.^2 + KY.^2) * sg^2 / 2);
    img = real(ifft2(W .* H));
    img = (img - min(img(:))) / (max(img(:)) - min(img(:)));
    kx1 = ifftshift(-floor(N/2):ceil(N/2)-1) * (2*pi/N);   % 1-D wavenumbers

    for subset = subsets
        Pc = P; Pc.subset_size = subset;
        bu = nan(size(deltas)); bv = bu; su = bu; np = bu;
        t0 = tic;
        for i = 1:numel(deltas)
            d = deltas(i);
            % exact periodic Fourier shift by +d px along x
            shifted = real(ifft(fft(img, [], 2) .* exp(-1i * d * kx1), [], 2));
            R = dic_engine_batch(img, shifted, Pc);
            u = R.U(isfinite(R.U));  v = R.V(isfinite(R.V));
            bu(i) = mean(u) - d;     % systematic error at this delta
            bv(i) = mean(v);
            su(i) = std(u);
            np(i) = numel(u);
        end
        % slope of the S-curve = relative apparent strain
        slope = diff(bu) ./ diff(deltas);
        res(end+1) = struct('sigma', sg, 'subset', subset, 'delta', deltas, ...
            'bias_u', bu, 'bias_v', bv, 'scatter_u', su, 'npts', np); %#ok<SAGROW>
        fprintf(['sigma %.1f, subset %2d: b = %.2e px, apparent strain ' ...
                 '(max |slope|) = %.2f %%, cross-talk v = %.1e px, ' ...
                 '%d pts/shift (%.0f s)\n'], ...
            sg, subset, max(abs(bu)), 100 * max(abs(slope)), ...
            max(abs(bv)), round(mean(np)), toc(t0));
    end
end
fprintf('Total sweep time: %.0f s\n', toc(t_all));

%% ===================== Figure =====================
figure('Name', 'Interpolation-bias S-curve', 'Color', 'w', ...
       'Position', [80 80 640 480]);
hold on; grid on; box on;
for i = 1:numel(res)
    plot(res(i).delta, 1e3 * res(i).bias_u, 'o-', 'LineWidth', 1.2, ...
        'DisplayName', sprintf('\\sigma = %.1f px, subset %d', ...
        res(i).sigma, res(i).subset));
end
yline(0, 'k:', 'HandleVisibility', 'off');
xlabel('applied subpixel shift \delta, px');
ylabel('displacement bias  u_{meas} - \delta,  10^{-3} px');
title('Interpolation-bias S-curve (Fourier-shift sweep)');
legend('Location', 'best');

%% ===================== Save =====================
save(fullfile(this_dir, 'bias_scurve_results.mat'), 'res', 'P', ...
     'deltas', 'sigmas', 'subsets', 'N');
fprintf('Saved bias_scurve_results.mat to %s\n', this_dir);
